Shell(BASE=http://localhost:4000 TOKEN=$(cat /tmp/gktv-token.txt) AUTH="authorization: Bearer $TOKEN" J='content-type: application/json' echo "=== 11. create (future-dated, should stay hidden from public) ===" NEW=$(curl -sS -X POST "$BASE/api/admin/stories" -H "$AUTH" -H "$J" \ -d '{"slug":"smoke-test-dispatch","category":"Kashmir","title":"A smoke test dispatch","summary":"Temporary row.","author":"QA","image_key":"lead","featured":false,"display_order":99,"published_at":"2030-01-01T00:00:00.000Z"}') ID=$(echo "$NEW" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{console.log(JSON.parse(d).data.id)})") echo "created id: $ID" echo -n "public total (should still be 12): "; curl -sS "$BASE/api/stories" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).meta.total))" echo -n "hidden slug via public (expect 404): "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/stories/smoke-test-dispatch" echo -n "admin total (should be 13): "; curl -sS "$BASE/api/admin/stories" -H "$AUTH" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).meta.total))" echo "=== 12. duplicate slug (expect 409) ===" curl -sS -o /dev/null -w "%{http_code}
" -X POST "$BASE/api/admin/stories" -H "$AUTH" -H "$J" \ -d '{"slug":"smoke-test-dispatch","category":"Kashmir","title":"dup","summary":"dup","author":"QA","image_key":"lead"}' echo "=== 13. validation error (expect 422 + details) ===" curl -sS -X POST "$BASE/api/admin/stories" -H "$AUTH" -H "$J" -d '{"slug":"Bad Slug","title":""}'; echo echo "=== 14. update (partial: publish it now) ===" curl -sS -X PUT "$BASE/api/admin/stories/$ID" -H "$AUTH" -H "$J" \ -d '{"published_at":"2020-01-01T00:00:00.000Z","featured":true}' \ | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{const s=JSON.parse(d).data;console.log('featured:',s.featured,'| published_at:',s.published_at)})" echo -n "now visible publicly (expect 200): "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/stories/smoke-test-dispatch" echo "=== 15. 404s ===" echo -n "unknown slug: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/stories/nope-nope" echo -n "unknown id: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/admin/stories/11111111-1111-4111-8111-111111111111" -H "$AUTH" echo -n "bad id uuid: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/admin/stories/not-a-uuid" -H "$AUTH" echo -n "unknown route:"; curl -sS -o /dev/null -w " %{http_code}
" "$BASE/api/does-not-exist" echo -n "bad token: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/admin/stories" -H "authorization: Bearer nope.nope.nope" echo "=== 16. delete (expect 204 then 404) ===" echo -n "delete: "; curl -sS -o /dev/null -w "%{http_code}
" -X DELETE "$BASE/api/admin/stories/$ID" -H "$AUTH" echo -n "re-delete:"; curl -sS -o /dev/null -w " %{http_code}
" -X DELETE "$BASE/api/admin/stories/$ID" -H "$AUTH" echo -n "final public total (expect 12): "; curl -sS "$BASE/api/stories" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).meta.total))" echo "=== 17. CORS preflight ===" curl -sS -o /dev/null -D - -X OPTIONS "$BASE/api/stories" -H "Origin: http://localhost:8080" -H "Access-Control-Request-Method: GET" 2>/dev/null | grep -i "access-control-allow-origin\|HTTP/")

Shell(S="$COMMANDCODE_SCRATCHPAD" BASE=http://localhost:4000 REPO=/Users/apple/coding/paid-projects-ns/kashmir-connect # --- fixtures --- node -e " const fs=require('fs'); const png=Buffer.alloc(9*1024*1024); Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]).copy(png,0); fs.writeFileSync('$S/oversized.png',png); const head=Buffer.from([0x00,0x00,0x00,0x18,0x66,0x74,0x79,0x70,0x69,0x73,0x6f,0x6d,0x00,0x00,0x02,0x00,0x69,0x73,0x6f,0x6d,0x69,0x73,0x6f,0x32]); fs.writeFileSync('$S/clip.mp4',Buffer.concat([head,Buffer.alloc(8192)])); " printf 'this file is plain text pretending to be a photo' > "$S/fake.jpg" curl -sS --retry 15 --retry-connrefused --retry-delay 1 "$BASE/api/health" >/dev/null && echo "api up" TOKEN=$(curl -s -X POST "$BASE/api/auth/login" -H 'content-type: application/json' -d '{"email":"admin@gktv.local","password":"ChangeMe123!"}' | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).data.token))") AUTH="authorization: Bearer $TOKEN" echo "token: ${#TOKEN} chars" echo; echo "=== 1. valid image upload ===" UP=$(curl -s -X POST "$BASE/api/admin/media" -H "$AUTH" -F "file=@$REPO/src/assets/kashmir-lead.jpg;type=image/jpeg" -F "width=1536" -F "height=1024") echo "$UP" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{const m=JSON.parse(d).data;console.log('kind:',m.kind,'| url:',m.url,'| w/h:',m.width+'x'+m.height,'| bytes:',m.size_bytes)})" IMG_URL=$(echo "$UP" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).data.url))") IMG_ID=$(echo "$UP" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).data.id))") echo "=== 2. served + content-type + Range (video seeking mechanism) ===" curl -s -o /dev/null -w " full: %{http_code} type=%{content_type} size=%{size_download}
" "$BASE$IMG_URL" curl -s -o /dev/null -w " range: %{http_code} (expect 206)
" -H "Range: bytes=0-99" "$BASE$IMG_URL" curl -s -o /dev/null -D - "$BASE$IMG_URL" 2>/dev/null | grep -i "cross-origin-resource-policy" | sed 's/^/ /' echo "=== 3. text file renamed .jpg (expect 415) ===" curl -s -o /tmp/r3.json -w " status %{http_code}
" -X POST "$BASE/api/admin/media" -H "$AUTH" -F "file=@$S/fake.jpg;type=image/jpeg" node -e "const j=require('/tmp/r3.json');console.log(' ->',j.error.message)" echo "=== 4. oversized image (expect 413) ===" curl -s -o /tmp/r4.json -w " status %{http_code}
" -X POST "$BASE/api/admin/media" -H "$AUTH" -F "file=@$S/oversized.png;type=image/png" echo "=== 5. video upload (mp4 header) ===" curl -s -X POST "$BASE/api/admin/media" -H "$AUTH" -F "file=@$S/clip.mp4;type=video/mp4" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{const m=JSON.parse(d).data;console.log(' kind:',m.kind,'| mime:',m.mime,'| url:',m.url)})" echo "=== 6. unauthenticated upload (expect 401) ===" curl -s -o /dev/null -w " status %{http_code}
" -X POST "$BASE/api/admin/media" -F "file=@$REPO/src/assets/kashmir-lead.jpg;type=image/jpeg" echo "=== 7. leftover files on disk (rejects must not persist) ===" find "$REPO/server/uploads" -type f | wc -l | sed 's/^/ files: /' PARTIAL=$(find "$REPO/server/uploads" -type f -size +8M | wc -l | tr -d ' ') echo " files over 8MB (should be 0): $PARTIAL" echo "$IMG_URL" > "$S/img_url.txt"; echo "$IMG_ID" > "$S/img_id.txt"; echo "$TOKEN" > "$S/token.txt")
